-- 去除路线产品展示快照；身份关联和业务事实保留原值。
DELIMITER $$
CREATE PROCEDURE mes_v66_remove_routing_snapshots()
BEGIN
    DECLARE snapshot_count INT;
    DECLARE column_count INT;
    SELECT COUNT(*) INTO snapshot_count FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND COLUMN_NAME IN ('material_code','material_name');
    SELECT COUNT(*) INTO column_count FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product';
    IF NOT (EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND BINARY `TABLE_NAME`=BINARY 'routing_product' AND BINARY `ORDINAL_POSITION`=BINARY '1' AND BINARY `COLUMN_NAME`=BINARY 'id' AND BINARY `COLUMN_TYPE`=BINARY 'bigint' AND BINARY `IS_NULLABLE`=BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA`=BINARY 'auto_increment' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT`=BINARY '路线适用物料产品关系本地主键')
        AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND BINARY `TABLE_NAME`=BINARY 'routing_product' AND BINARY `ORDINAL_POSITION`=BINARY '2' AND BINARY `COLUMN_NAME`=BINARY 'routing_id' AND BINARY `COLUMN_TYPE`=BINARY 'bigint' AND BINARY `IS_NULLABLE`=BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA`=BINARY '' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT`=BINARY '所属路线确切版本主键，工厂边界继承父级')
        AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND BINARY `TABLE_NAME`=BINARY 'routing_product' AND BINARY `ORDINAL_POSITION`=BINARY '3' AND BINARY `COLUMN_NAME`=BINARY 'material_id' AND BINARY `COLUMN_TYPE`=BINARY 'bigint' AND BINARY `IS_NULLABLE`=BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA`=BINARY '' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT`=BINARY '引用的物料产品本地主键')
        AND EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ENGINE` = BINARY 'InnoDB' AND BINARY `TABLE_COLLATION` = BINARY 'utf8mb4_0900_ai_ci' AND BINARY `TABLE_COMMENT` = BINARY '路线版本适用的物料产品集合')
          AND (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('routing_product')) = 1
        AND EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `INDEX_NAME` = BINARY 'idx_routing_product_material' AND BINARY `NON_UNIQUE` = BINARY '1' AND BINARY `SEQ_IN_INDEX` = BINARY '1' AND BINARY `COLUMN_NAME` = BINARY 'material_id' AND BINARY `COLLATION` = BINARY 'A' AND `SUB_PART` IS NULL AND BINARY `INDEX_TYPE` = BINARY 'BTREE' AND BINARY `IS_VISIBLE` = BINARY 'YES' AND `EXPRESSION` IS NULL)
          AND EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `INDEX_NAME` = BINARY 'PRIMARY' AND BINARY `NON_UNIQUE` = BINARY '0' AND BINARY `SEQ_IN_INDEX` = BINARY '1' AND BINARY `COLUMN_NAME` = BINARY 'id' AND BINARY `COLLATION` = BINARY 'A' AND `SUB_PART` IS NULL AND BINARY `INDEX_TYPE` = BINARY 'BTREE' AND BINARY `IS_VISIBLE` = BINARY 'YES' AND `EXPRESSION` IS NULL)
          AND EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `INDEX_NAME` = BINARY 'uk_routing_product_material' AND BINARY `NON_UNIQUE` = BINARY '0' AND BINARY `SEQ_IN_INDEX` = BINARY '1' AND BINARY `COLUMN_NAME` = BINARY 'routing_id' AND BINARY `COLLATION` = BINARY 'A' AND `SUB_PART` IS NULL AND BINARY `INDEX_TYPE` = BINARY 'BTREE' AND BINARY `IS_VISIBLE` = BINARY 'YES' AND `EXPRESSION` IS NULL)
          AND EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `INDEX_NAME` = BINARY 'uk_routing_product_material' AND BINARY `NON_UNIQUE` = BINARY '0' AND BINARY `SEQ_IN_INDEX` = BINARY '2' AND BINARY `COLUMN_NAME` = BINARY 'material_id' AND BINARY `COLLATION` = BINARY 'A' AND `SUB_PART` IS NULL AND BINARY `INDEX_TYPE` = BINARY 'BTREE' AND BINARY `IS_VISIBLE` = BINARY 'YES' AND `EXPRESSION` IS NULL)
          AND (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('routing_product')) = 4
        AND EXISTS (SELECT 1 FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND CONSTRAINT_NAME='PRIMARY' AND CONSTRAINT_TYPE='PRIMARY KEY')
          AND EXISTS (SELECT 1 FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND CONSTRAINT_NAME='uk_routing_product_material' AND CONSTRAINT_TYPE='UNIQUE')
          AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('routing_product')) = 2) OR column_count <> 3 + snapshot_count THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V66 routing identity schema differs; stop before DDL';
    END IF;
    IF snapshot_count = 2 THEN
        IF NOT (EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ORDINAL_POSITION` = BINARY '1' AND BINARY `COLUMN_NAME` = BINARY 'id' AND BINARY `COLUMN_TYPE` = BINARY 'bigint' AND BINARY `IS_NULLABLE` = BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA` = BINARY 'auto_increment' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT` = BINARY '路线适用物料产品关系本地主键')
          AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ORDINAL_POSITION` = BINARY '2' AND BINARY `COLUMN_NAME` = BINARY 'routing_id' AND BINARY `COLUMN_TYPE` = BINARY 'bigint' AND BINARY `IS_NULLABLE` = BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA` = BINARY '' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT` = BINARY '所属路线确切版本主键，工厂边界继承父级')
          AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ORDINAL_POSITION` = BINARY '3' AND BINARY `COLUMN_NAME` = BINARY 'material_id' AND BINARY `COLUMN_TYPE` = BINARY 'bigint' AND BINARY `IS_NULLABLE` = BINARY 'NO' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA` = BINARY '' AND `COLLATION_NAME` IS NULL AND BINARY `COLUMN_COMMENT` = BINARY '引用的物料产品本地主键')
          AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ORDINAL_POSITION` = BINARY '4' AND BINARY `COLUMN_NAME` = BINARY 'material_code' AND BINARY `COLUMN_TYPE` = BINARY 'varchar(64)' AND BINARY `IS_NULLABLE` = BINARY 'YES' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA` = BINARY '' AND BINARY `COLLATION_NAME` = BINARY 'utf8mb4_0900_ai_ci' AND BINARY `COLUMN_COMMENT` = BINARY '发布时冻结的物料产品编码，草稿可为空')
          AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND BINARY `TABLE_NAME` = BINARY 'routing_product' AND BINARY `ORDINAL_POSITION` = BINARY '5' AND BINARY `COLUMN_NAME` = BINARY 'material_name' AND BINARY `COLUMN_TYPE` = BINARY 'varchar(255)' AND BINARY `IS_NULLABLE` = BINARY 'YES' AND `COLUMN_DEFAULT` IS NULL AND BINARY `EXTRA` = BINARY '' AND BINARY `COLLATION_NAME` = BINARY 'utf8mb4_0900_ai_ci' AND BINARY `COLUMN_COMMENT` = BINARY '发布时冻结的物料产品名称，草稿可为空')
          AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('routing_product')) = 5) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V66 snapshot schema drift; stop before DDL';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND COLUMN_NAME='material_code' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='YES')
          OR NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='routing_product' AND COLUMN_NAME='material_name' AND COLUMN_TYPE='varchar(255)' AND IS_NULLABLE='YES') THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V66 snapshot columns differ; stop before DDL';
        END IF;
        ALTER TABLE routing_product DROP COLUMN material_code, DROP COLUMN material_name;
    ELSEIF snapshot_count <> 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V66 partial snapshot columns; stop before DDL';
    END IF;
END$$
CALL mes_v66_remove_routing_snapshots()$$
DROP PROCEDURE mes_v66_remove_routing_snapshots$$
DELIMITER ;
